int main(void) {
    size_t quantidade;

    printf("Quantidade de números: ");
    if (scanf("%zu", &quantidade) != 1 || quantidade == 0) {
        fprintf(stderr, "Quantidade inválida.\n");
        return 1;
    }

    int *numeros = malloc(quantidade * sizeof(*numeros));

    if (numeros == NULL) {
        fprintf(stderr, "Falha ao alocar memória.\n");
        return 1;
    }

    long long soma = 0;

    for (size_t i = 0; i < quantidade; i++) {
        printf("Número %zu: ", i + 1);

        if (scanf("%d", &numeros[i]) != 1) {
